<script setup>
import { computed, onMounted, ref } from "vue";
import { exportProgress, hasProgress, loadProgress, progressState, resetProgress } from "../lib/progressStore.js";
const props=defineProps({lessons:Array,modules:Array,base:String});const dialog=ref();onMounted(loadProgress);const returning=computed(()=>progressState.value&&hasProgress());const published=computed(()=>props.lessons.filter(x=>x.status==='published'));const current=computed(()=>props.lessons.find(x=>x.id===progressState.value?.currentLesson)||published.value[0]);const section=computed(()=>progressState.value?.lastSections?.[current.value.id]||'welcome');const url=p=>`${props.base.endsWith('/')?props.base:`${props.base}/`}${p.replace(/^\//,'')}`;const resume=computed(()=>`${url(`/lessons/${current.value.id}`)}#${section.value}`);function readable(v){return v==='welcome'?'Lesson introduction':v.replaceAll('-',' ').replace(/\b\w/g,l=>l.toUpperCase())}function status(x){if(progressState.value?.completedLessons.includes(x.id))return'Completed';if(returning.value&&current.value.id===x.id)return'You are here';return x.status==='published'?'Available':'Planned'}function restart(){resetProgress();dialog.value.close()}
</script>
<template><main v-if="progressState" class="home-course"><section v-if="returning" class="resume-card"><div><span>WELCOME BACK</span><h2>{{current.title}}</h2><p>You stopped at <strong>{{readable(section)}}</strong>.</p></div><a class="lg-button lg-button--primary" :href="resume">Resume this section →</a></section><section class="home-explainer"><article><span>01</span><h2>What this is</h2><p>Complete walkthroughs of real terminal scenarios, followed by deeper lessons on the machinery you already encountered.</p></article><article><span>02</span><h2>How to use it</h2><p>Follow the data, open optional interactive diagrams, inspect narrow source excerpts, and use any AI only when you want another perspective.</p></article><article><span>03</span><h2>Who it is for</h2><p>Senior engineers with no assumed PTY, terminal protocol, Zig, font, GPU, GTK, SwiftUI, tmux, or SSH internals knowledge.</p></article></section><section id="roadmap" class="home-roadmap"><header><div><span>THE COMPLETE PATH</span><h2>What you will learn</h2></div><p>Every published lesson is open. The order is recommended, never enforced.</p></header><section v-for="mod in modules" :key="mod.name" class="roadmap-module"><div class="roadmap-module__title"><h3>{{mod.name}}</h3><p>{{mod.summary}}</p></div><div class="roadmap-lessons"><component :is="x.status==='published'?'a':'div'" v-for="x in mod.lessons" :key="x.id" :href="x.status==='published'?url(`/lessons/${x.id}`):undefined" :class="['roadmap-lesson',{current:returning&&current.id===x.id,completed:progressState.completedLessons.includes(x.id)}]"><span>{{String(x.order).padStart(2,'0')}}</span><div><strong>{{x.title}}</strong><small>{{x.summary}}</small></div><b>{{status(x)}}</b></component></div></section></section><section class="contributor-callout"><div><span>FOR REAL HUMAN CONTRIBUTORS</span><h2>Want to contribute to the Ghostty ecosystem?</h2><p>Learn to trace behavior, reproduce bugs, read the relevant Zig or platform code, add regression tests, and own a change as a human—not merely generate a patch.</p></div><div class="contributor-links"><a href="https://github.com/ghostty-org/ghostty/blob/main/CONTRIBUTING.md">Contribution guide</a><a href="https://github.com/ghostty-org/ghostty/blob/main/AI_POLICY.md">AI usage policy</a><a href="https://ghostty.org/docs">Official Ghostty docs</a></div></section><footer class="home-progress-tools"><div><strong>Your progress stays in this browser.</strong><span>Export a backup or restart whenever you want.</span></div><div><button @click="exportProgress">Export progress</button><button class="danger" @click="dialog.showModal()">Restart progress</button></div></footer><dialog ref="dialog" class="reset-dialog"><form method="dialog"><button class="dialog-close" aria-label="Close">×</button></form><span>RESTART FROM SCRATCH</span><h2>Erase browser progress?</h2><p>This removes completed lessons and resume positions from this browser.</p><div><button @click="exportProgress">Export backup</button><form method="dialog"><button>Cancel</button></form><button class="danger" @click="restart">Restart everything</button></div></dialog></main></template>
